CREATE SCHEMA NLP;
CREATE TABLE NLP.SCRIPT_FAMILY (SCRIPT_ID VARCHAR(36) NOT NULL PRIMARY KEY, CANONICAL_CODE VARCHAR(64) NOT NULL UNIQUE, NAME VARCHAR(200) NOT NULL, FAMILY VARCHAR(200), WRITING_DIRECTION VARCHAR(16) NOT NULL DEFAULT 'unknown', DECIPHERMENT_STATUS VARCHAR(32) NOT NULL DEFAULT 'partial', CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP);
CREATE TABLE NLP.SOURCE_DOCUMENT (DOCUMENT_ID VARCHAR(36) NOT NULL PRIMARY KEY, EXTERNAL_ID VARCHAR(256), TITLE CLOB(2M), URI CLOB(2M), MEDIA_TYPE VARCHAR(128), CHECKSUM_SHA256 CHAR(64), CAPTURED_AT TIMESTAMP, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP);
CREATE TABLE NLP.INSCRIPTION (INSCRIPTION_ID VARCHAR(36) NOT NULL PRIMARY KEY, DOCUMENT_ID VARCHAR(36), SCRIPT_ID VARCHAR(36) NOT NULL, SCHOLARLY_ID VARCHAR(256), LANGUAGE_CODE VARCHAR(64), TRANSLITERATION CLOB(4M), TRANSLATION CLOB(4M), CONFIDENCE DECIMAL(6,5), UNCERTAINTY CLOB(1M), PROVENANCE CLOB(1M), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP, FOREIGN KEY(DOCUMENT_ID) REFERENCES NLP.SOURCE_DOCUMENT(DOCUMENT_ID), FOREIGN KEY(SCRIPT_ID) REFERENCES NLP.SCRIPT_FAMILY(SCRIPT_ID));
CREATE TABLE NLP.GLYPH_OBSERVATION (GLYPH_ID VARCHAR(36) NOT NULL PRIMARY KEY, INSCRIPTION_ID VARCHAR(36) NOT NULL, SEQUENCE_NO INTEGER NOT NULL, UNICODE_CODEPOINT VARCHAR(32), GLYPH_LABEL VARCHAR(128), BOUNDING_BOX CLOB(64K), IMAGE_URI CLOB(1M), RECOGNIZED_TEXT CLOB(1M), CONFIDENCE DECIMAL(6,5), DAMAGED SMALLINT NOT NULL DEFAULT 0, ALTERNATE_READINGS CLOB(1M), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP, CONSTRAINT UQ_GLYPH_SEQ UNIQUE(INSCRIPTION_ID,SEQUENCE_NO), FOREIGN KEY(INSCRIPTION_ID) REFERENCES NLP.INSCRIPTION(INSCRIPTION_ID));
CREATE TABLE NLP.READING (READING_ID VARCHAR(36) NOT NULL PRIMARY KEY, INSCRIPTION_ID VARCHAR(36) NOT NULL, READING_TEXT CLOB(4M) NOT NULL, TRANSLITERATION CLOB(4M), NORMALIZED_TEXT CLOB(4M), CONFIDENCE DECIMAL(6,5), REVIEWER VARCHAR(256), EVIDENCE CLOB(1M), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP, FOREIGN KEY(INSCRIPTION_ID) REFERENCES NLP.INSCRIPTION(INSCRIPTION_ID));
CREATE TABLE NLP.TRANSLATION_CANDIDATE (CANDIDATE_ID VARCHAR(36) NOT NULL PRIMARY KEY, READING_ID VARCHAR(36) NOT NULL, TARGET_LANGUAGE VARCHAR(32) NOT NULL, TRANSLATION CLOB(4M) NOT NULL, MODEL_ID VARCHAR(36), CONFIDENCE DECIMAL(6,5), RANK_NO INTEGER, EVIDENCE CLOB(1M), HUMAN_VERIFIED SMALLINT NOT NULL DEFAULT 0, CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP, FOREIGN KEY(READING_ID) REFERENCES NLP.READING(READING_ID));
CREATE TABLE NLP.MODEL_REGISTRY (MODEL_ID VARCHAR(36) NOT NULL PRIMARY KEY, MODEL_NAME VARCHAR(256) NOT NULL UNIQUE, ARCHITECTURE VARCHAR(128), TASK VARCHAR(128), PROVIDER VARCHAR(256), LICENSE VARCHAR(256), METADATA CLOB(1M), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP);
CREATE TABLE NLP.MODEL_VERSION (MODEL_VERSION_ID VARCHAR(36) NOT NULL PRIMARY KEY, MODEL_ID VARCHAR(36) NOT NULL, VERSION VARCHAR(128) NOT NULL, ARTIFACT_URI CLOB(1M), CHECKSUM_SHA256 CHAR(64), PARAMETERS BIGINT, FRAMEWORK VARCHAR(128), METRICS CLOB(1M), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP, CONSTRAINT UQ_MODEL_VERSION UNIQUE(MODEL_ID,VERSION), FOREIGN KEY(MODEL_ID) REFERENCES NLP.MODEL_REGISTRY(MODEL_ID));
CREATE TABLE NLP.INFERENCE_RUN (RUN_ID VARCHAR(36) NOT NULL PRIMARY KEY, MODEL_VERSION_ID VARCHAR(36), INSCRIPTION_ID VARCHAR(36), OPERATION VARCHAR(64) NOT NULL, INPUT_HASH CHAR(64), OUTPUT CLOB(4M), LATENCY_MS DECIMAL(18,3), CONFIDENCE DECIMAL(6,5), CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP);
